-- 0235 — Academy, niveau 1, leçon 6 : trois simulateurs interactifs (2026-11-14).
--
-- Atelier « Choisissez votre ordre » (type `carnet`, règlement BRVM art. 44 à
-- 46, carnet fictif + carnet réel lu via /api/academy/carnet), répartition par
-- secteur (`allocation`) et scénarios de baisse (`scenario_baisse`).
-- ⚠️ À APPLIQUER APRÈS le déploiement du frontend : le schéma zod des leçons doit
-- déjà connaître ces trois types (et le champ `simulations`), sinon la leçon ne
-- se parserait plus. Aucun chiffre de marché : hypothèses de la leçon seulement.
-- Source : frontend/lib/academy/contenus/lecon6-risques.json (testé).
-- Fusion `||` sur la leçon d'index 5 (les clés absentes, image…, sont conservées).
-- Garde d'idempotence : ne s'applique qu'une fois (marqueur = une simulation de
-- type `carnet` dans la leçon 6).

update public.academy_courses
   set content = jsonb_set(content, '{lessons,5}', (content->'lessons'->5) || $wb${"titre": "Leçon 6 — Les risques : apprendre avant d'investir", "categorie": "general", "duree_min": 12, "sous_titre": "Anticiper une perte, protéger son capital, passer un ordre correctement, et décider calmement quand le marché baisse.", "resume": "Investir en actions, c’est accepter l’incertitude : un cours peut baisser, un dividende peut diminuer, une action peut être difficile à revendre. Cette leçon apprend à identifier les trois grands risques, à s’en protéger, à choisir le bon ordre de bourse selon les règles de la BRVM, et à réagir avec méthode à une baisse.", "avertissement": "Ceci n’est pas un conseil en investissement. Les actions comportent un risque de perte partielle ou totale du capital. Les dividendes ne sont jamais garantis et les performances passées ne préjugent pas des performances futures. Les seuils et allocations cités sont pédagogiques.", "sections": [{"type": "definition", "titre": "Les trois risques à connaître", "contenu": "Un investisseur averti ne fuit pas le risque : il cherche à savoir d’où il vient et ce qu’il peut coûter. Trois risques principaux demandent votre attention.\nSur la BRVM, le troisième compte particulièrement : les volumes échangés varient fortement d’une valeur à l’autre.", "points": [{"titre": "Le risque de marché", "detail": "Une crise, une hausse des taux ou une perte de confiance fait baisser de nombreuses actions en même temps, même les plus solides. La diversification ne l’efface pas.", "verifier": "Pourriez-vous supporter une baisse temporaire de 15 à 20 % sans être obligé de vendre ?"}, {"titre": "Le risque propre à une entreprise", "detail": "Chiffre d’affaires en baisse, rentabilité dégradée, dette excessive, mauvaise décision, perte d’un marché : une seule société peut chuter de 25 % sur une mauvaise nouvelle.", "verifier": "Les derniers résultats de chaque société que vous détenez."}, {"titre": "Le risque de liquidité", "detail": "Une action peut afficher un cours sans qu’il y ait assez d’acheteurs pour vendre vite à ce prix. Il faut alors attendre, fractionner la vente, ou accepter un prix plus bas.", "verifier": "Les volumes échangés, la fréquence des échanges et l’écart entre prix acheteur et vendeur."}]}, {"type": "cas", "titre": "Quand le dividende baisse : des cas réels", "reel": true, "contenu": "Un dividende dépend des bénéfices, de la trésorerie, des investissements à financer et de la décision de l’assemblée générale. Il n’est jamais garanti. Voici l’historique de quatre sociétés cotées, lu dans la base WestBourse à l’ouverture de la leçon.\nAvant de choisir une action pour son dividende, posez-vous quatre questions.", "donnees_reelles": {"vue": "historique", "codes": ["SNTS", "PALC", "NTLC", "SPHC"]}, "points": [{"titre": "L’entreprise réalise-t-elle des bénéfices réguliers ?"}, {"titre": "Sa trésorerie finance-t-elle à la fois son activité et sa distribution ?"}, {"titre": "Son endettement reste-t-il maîtrisé ?"}, {"titre": "Le dividende est-il soutenable dans les années qui viennent ?", "detail": "Un rendement très élevé peut venir d’un cours qui a fortement baissé : ce n’est pas automatiquement une affaire."}]}, {"type": "importance", "titre": "Trois protections, et l’effet de la diversification", "contenu": "Aucun investissement n’est sans risque. Trois principes évitent pourtant les erreurs les plus coûteuses.\nExemple pédagogique : 1 000 000 FCFA rapportant 8 % de dividendes, soit 80 000 FCFA par an. Une société divise son dividende par deux.", "points": [{"titre": "Diversifier", "detail": "Répartir entre plusieurs sociétés et secteurs. Repères pédagogiques pour un débutant : pas plus de 20 % sur une société, 35 % sur un secteur.", "verifier": "Deux sociétés différentes peuvent dépendre de la même matière première ou du même marché."}, {"titre": "Investir pour plusieurs années", "detail": "Un portefeuille de 1 000 000 FCFA qui vaut 850 000 FCFA six mois plus tard a perdu 15 % de valeur, même sans vente. Avec un horizon long, on n’est pas forcé de vendre au mauvais moment."}, {"titre": "Se former et suivre ses sociétés", "detail": "Chiffre d’affaires, résultat, marge, dette, trésorerie, dividendes, perspectives : un investissement ne s’arrête pas le jour de l’achat."}], "tableau": {"colonnes": ["Stratégie", "Revenu avant", "Revenu après", "Baisse"], "lignes": [["Tout sur une seule valeur", "80 000", "40 000", "−50 %"], ["Cinq valeurs à parts égales", "80 000", "72 000", "−10 %"]], "note": "Exemple pédagogique : cinq lignes de même montant et de même rendement ; une seule divise son dividende par deux. La diversification n’empêche pas les mauvaises nouvelles, elle évite qu’une seule les fasse toutes subir."}, "simulations": [{"type": "allocation", "capital": 1000000, "secteurs": [{"nom": "Banques", "pct": 20}, {"nom": "Télécoms", "pct": 20}, {"nom": "Agro-industrie", "pct": 20}, {"nom": "Distribution", "pct": 20}, {"nom": "Énergie", "pct": 20}], "seuil_secteur_pct": 35}, {"type": "scenario_baisse", "capital": 1000000, "rendement_pct": 8, "secteurs": [{"nom": "Banques", "pct": 20}, {"nom": "Télécoms", "pct": 20}, {"nom": "Agro-industrie", "pct": 20}, {"nom": "Distribution", "pct": 20}, {"nom": "Énergie", "pct": 20}]}]}, {"type": "importance", "titre": "Les ordres de bourse selon les règles de la BRVM", "contenu": "Choisir une bonne action ne suffit pas : un ordre mal rédigé peut faire payer trop cher, ou ne jamais s’exécuter. Le règlement général de la BRVM décrit un ordre par trois caractéristiques : sa limite de prix, sa durée de validité, et ce qu’il accepte en cas de réponse partielle.\nSelon la valeur, les ordres sont confrontés au fixing (un cours d’équilibre unique) ou en continu (chaque ordre rencontre aussitôt le carnet).", "tableau": {"colonnes": ["Caractéristique", "Ce que prévoit le règlement", "Ce que cela change pour vous"], "lignes": [["Limite de prix", "Au mieux : aucun prix fixé", "L’exécution est favorisée, le prix n’est pas maîtrisé"], ["Limite de prix", "À cours limité : prix maximal à l’achat, minimal à la vente", "Le prix est maîtrisé, l’exécution n’est pas garantie"], ["Validité", "Jour : présenté à la seule séance qui suit sa transmission (choix par défaut)", "Non exécuté, il disparaît"], ["Validité", "Mensuel : jusqu’à la dernière séance du mois", "Il reste en attente plusieurs séances"], ["Validité", "À exécution : sans date, présenté 3 mois au plus ; ou date limite choisie", "Il peut s’exécuter longtemps après votre décision"], ["Réponse partielle", "Sans condition : la quantité est un maximum", "Il peut être servi en partie"], ["Réponse partielle", "Tout ou rien", "Servi en totalité, ou pas du tout"]], "note": "Source : règlement général de la BRVM, articles 44 à 46 (version du 1er juillet 2022). Un ordre sans indication de limite est rejeté. D’autres conditions existent sur d’autres marchés (meilleure limite, exécuté ou éliminé) : demandez à votre SGI ce qu’elle propose."}}, {"type": "cas", "titre": "Mise en situation : acheter 5 000 actions", "contenu": "Carnet fictif, à but pédagogique. Les vendeurs proposent les quantités ci-dessous. Le cours affiché n’est pas forcément le prix auquel vous achèterez : tout dépend des quantités disponibles en face de vous.", "tableau": {"colonnes": ["Prix vendeur", "Quantité proposée"], "lignes": [["3 280 FCFA", "3 500"], ["3 290 FCFA", "4 500"], ["3 300 FCFA", "5 500"]], "note": "Carnet fictif : les quantités et les prix ne décrivent aucune valeur réelle."}, "formules": [{"nom": "Ordre au mieux pour 5 000 titres", "expression": "(3 500 × 3 280 + 1 500 × 3 290) ÷ 5 000", "exemple": "Prix moyen : 3 283 FCFA, au-dessus du meilleur prix affiché"}, {"nom": "Ordre à cours limité à 3 270 FCFA", "expression": "Aucun vendeur à 3 270 FCFA ou moins", "exemple": "Rien n’est exécuté : l’ordre attend selon sa validité"}, {"nom": "Tout ou rien : 10 000 titres limités à 3 290 FCFA", "expression": "3 500 + 4 500 = 8 000 titres disponibles à ce prix ou moins", "exemple": "Moins que les 10 000 demandés : aucune exécution"}], "etapes": [{"titre": "Le sens", "detail": "Achat ou vente ?"}, {"titre": "La quantité", "detail": "Combien de titres ?"}, {"titre": "Le prix", "detail": "Au mieux ou limité, et à quelle limite ?", "cle": true}, {"titre": "Le carnet", "detail": "Quelles quantités sont disponibles en face ?"}, {"titre": "La validité", "detail": "Jour, mensuel, à exécution ou date limite ?"}], "etapes_style": "frise", "simulation": {"type": "carnet", "niveaux": [{"prix": 3280, "quantite": 3500}, {"prix": 3290, "quantite": 4500}, {"prix": 3300, "quantite": 5500}], "quantite_defaut": 5000, "codes": ["SNTS", "SGBC", "ORAC", "PALC", "SPHC"]}}, {"type": "importance", "titre": "Une action perd 20 % : la méthode en trois étapes", "contenu": "Exemple : achetée 5 000 FCFA, l’action cote 4 000 FCFA quelques semaines plus tard, soit −20 %. Une baisse doit déclencher une analyse, pas une réaction.", "etapes": [{"titre": "Vérifier l’actualité", "detail": "Résultats publiés, changement de direction, perte d’un marché, réduction du dividende : la baisse vient-elle de l’entreprise, ou de tout le marché ?"}, {"titre": "Relire les fondamentaux", "detail": "Chiffre d’affaires, résultat net, dette, trésorerie, dividende soutenable, perspectives."}, {"titre": "Décider sans précipitation", "detail": "Conserver si les fondamentaux tiennent ; réduire si la ligne pèse trop ou si les perspectives se dégradent ; vendre si les raisons de l’achat ne tiennent plus.", "cle": true}], "points": [{"titre": "Une baisse n’est pas une affaire automatique", "detail": "Une société dont les comptes se dégradent peut continuer de baisser."}]}, {"type": "piege", "titre": "L’épargne de précaution, et les erreurs qui coûtent cher", "contenu": "Avant d’investir, gardez une réserve disponible pour les imprévus : santé, logement, scolarité, perte de revenus. Elle évite de vendre ses actions au mauvais moment.", "formules": [{"nom": "Épargne de précaution", "expression": "Dépenses mensuelles essentielles × 3 à 6 mois", "exemple": "250 000 × 6 = 1 500 000 FCFA, à garder hors du portefeuille boursier"}], "points": [{"titre": "Investir son épargne d’urgence", "detail": "Un imprévu oblige alors à vendre pendant une baisse."}, {"titre": "Vendre dans la panique", "detail": "Un cours qui baisse ne dit pas, à lui seul, que l’entreprise s’est affaiblie."}, {"titre": "Tout concentrer sur une valeur", "detail": "Un seul problème touche alors une grande partie du capital."}, {"titre": "Ignorer la liquidité", "detail": "Un ordre au mieux sur une valeur peu échangée peut s’exécuter à un prix défavorable."}, {"titre": "Acheter seulement pour le dividende", "detail": "Un rendement élevé peut cacher des résultats qui se dégradent."}, {"titre": "Suivre les rumeurs", "detail": "Décider sur des informations vérifiables : comptes, communiqués officiels, avis de la BRVM."}]}, {"type": "retenir", "titre": "Votre check-list avant le premier achat", "contenu": "Un investisseur discipliné ne prédit pas les baisses : il a une méthode pour les traverser. Si l’une de ces conditions manque, prenez le temps de la remplir avant de passer votre ordre.", "points": [{"titre": "Mon épargne de précaution est constituée", "detail": "Trois à six mois de dépenses essentielles, disponibles."}, {"titre": "Mon horizon est long", "detail": "Je peux laisser cet argent investi plusieurs années et accepter les variations."}, {"titre": "J’ai vérifié la liquidité de la valeur", "detail": "Volumes, fréquence des échanges, carnet d’ordres."}, {"titre": "J’ai étudié l’entreprise", "detail": "Dernier rapport annuel ou dernières publications."}, {"titre": "Je sais quel ordre je passe", "detail": "À cours limité si la valeur s’échange peu ; validité choisie, pas subie."}, {"titre": "Trois risques, trois protections", "detail": "Marché, entreprise, liquidité ; diversifier, investir longtemps, se former."}]}], "charts": [], "quiz": [{"question": "Pourquoi ne faut-il pas investir son épargne d’urgence en bourse ?", "options": ["Parce que les dividendes sont imposés", "Parce que la bourse est réservée aux résidents ivoiriens", "Parce qu’on peut avoir besoin de cet argent vite et devoir vendre pendant une baisse", "Parce que les SGI refusent les petits montants"], "correct": 2, "explication": "Les actions peuvent perdre de la valeur à court terme. Si un imprévu survient, vous pourriez devoir vendre à perte. L’épargne de précaution doit rester disponible, à l’écart des variations de la bourse."}, {"question": "Votre revenu de dividendes vient à parts égales de cinq sociétés. L’une divise son dividende par deux. De combien baisse votre revenu total ?", "options": ["−50 %", "−20 %", "−10 %", "−5 %"], "correct": 2, "explication": "Chaque société pèse 20 % du revenu. La moitié de 20 %, c’est 10 % du revenu total."}, {"question": "Quel risque la diversification réduit-elle le plus directement ?", "options": ["Le risque de marché", "Le risque propre à une entreprise", "Le risque de change", "Tous les risques à la fois"], "correct": 1, "explication": "Répartir entre plusieurs sociétés limite l’effet d’une mauvaise nouvelle sur l’une d’elles. Une baisse générale du marché, elle, touche toutes les lignes."}, {"question": "Qu’appelle-t-on le risque de liquidité ?", "options": ["La perte de valeur due à l’inflation", "La difficulté à vendre rapidement sans faire baisser le prix", "La faillite d’une société cotée", "La variation du franc CFA"], "correct": 1, "explication": "Sur une valeur peu échangée, il peut y avoir peu d’acheteurs : il faut alors attendre, ou accepter un prix plus bas."}, {"question": "Vos dépenses mensuelles essentielles sont de 200 000 FCFA. Combien prévoir pour six mois d’épargne de précaution ?", "options": ["600 000 FCFA", "1 200 000 FCFA", "2 000 000 FCFA", "200 000 FCFA"], "correct": 1, "explication": "200 000 × 6 = 1 200 000 FCFA, à garder disponibles et séparés du portefeuille boursier."}, {"question": "Vous passez un ordre d’achat à cours limité à 3 270 FCFA ; le vendeur le moins cher demande 3 280 FCFA. Que se passe-t-il ?", "options": ["L’ordre est exécuté à 3 280 FCFA", "L’ordre attend, selon sa validité, qu’un vendeur accepte 3 270 FCFA ou moins", "L’ordre est exécuté à 3 270 FCFA quoi qu’il arrive", "La BRVM rejette l’ordre"], "correct": 1, "explication": "Un ordre à cours limité ne s’exécute jamais au-delà de sa limite. Il reste en attente pendant sa durée de validité."}, {"question": "Que signifie un ordre « tout ou rien » ?", "options": ["Il est exécuté au meilleur prix disponible", "Il ne peut pas être servi partiellement", "Il reste valable trois mois", "Il n’a pas de limite de prix"], "correct": 1, "explication": "Le règlement général de la BRVM définit l’ordre « tout ou rien » comme un ordre qui ne peut pas être répondu partiellement."}, {"question": "Vous ne précisez pas la durée de validité de votre ordre. Comment est-il considéré ?", "options": ["Mensuel", "Jour : présenté à la seule séance qui suit sa transmission", "À exécution, pendant trois mois", "Annulé"], "correct": 1, "explication": "Selon le règlement général de la BRVM, un ordre sans indication de validité est réputé « jour »."}], "qcm": {"question": "Pourquoi ne faut-il pas investir son épargne d’urgence en bourse ?", "options": ["Parce que les dividendes sont imposés", "Parce que la bourse est réservée aux résidents ivoiriens", "Parce qu’on peut avoir besoin de cet argent vite et devoir vendre pendant une baisse", "Parce que les SGI refusent les petits montants"], "correct": 2, "explication": "Les actions peuvent perdre de la valeur à court terme. Si un imprévu survient, vous pourriez devoir vendre à perte. L’épargne de précaution doit rester disponible, à l’écart des variations de la bourse."}, "liens": [{"label": "Classement de liquidité", "href": "/liquidite"}, {"label": "Espace dividendes", "href": "/dividendes"}, {"label": "Choisir sa SGI", "href": "/comparateur-sgi"}]}$wb$::jsonb),
       updated_at = now()
 where slug = 'academy-niveau-1-initiation'
   and content->'lessons'->5->>'titre' = $wb$Leçon 6 — Les risques : apprendre avant d'investir$wb$
   and not jsonb_path_exists(content, '$.lessons[5].sections[*].simulation ? (@.type == "carnet")');
